 writing=any(c in (args[1] or '') for c in 'wax+') or bool((args[2] or 0)&(os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC))
 if writing and not p.is_relative_to(OUT):raise PermissionError('Parent write denied')
 code=any(p.is_relative_to(ROOT/k) for k in ['src','tests']) and p.suffix in ['.py','.pyc']
 if not (p.is_relative_to(OUT) or p in ALLOWED or code or p.is_relative_to(ROOT/'.venv') or p.name in ['.gitignore','pyproject.toml'] and p.parent==ROOT):raise PermissionError('Scientific payload denied')
 if not writing:READS.add(rel(p))
